    cudaError_t attr_status = cudaFuncSetAttribute(
        reinterpret_cast<const void*>(&layernorm_fused_kernel),
        cudaFuncAttributeMaxDynamicSharedMemorySize,
        static_cast<int>(max_smem_optin));
    if (attr_status != cudaSuccess) (void)cudaGetLastError();
    smem_attr_done = true;
  }
  // Register-cache dispatch: if the whole normalized row can be covered by
  // a co-resident cooperative grid where every thread holds LN_RCACHE float4
  // values of x in registers across the grid sync, launch the register-
  // caching kernel. This eliminates the second global-memory read of x
  // entirely (the profiler shows the shared-memory staging path is not
  // taken on this device, so the fallback currently re-reads x), without
  // spending any shared memory or occupancy on staging.
  if (vec) {
    int max_bps_rc = 0;
    cudaOccupancyMaxActiveBlocksPerMultiprocessor(
        &max_bps_rc,
        layernorm_rcache_kernel,
        threads,
