        const dim3 rc_blocks(static_cast<unsigned int>(gr), static_cast<unsigned int>(ch));
        auto rc_stream = at::cuda::getCurrentCUDAStream();
        const float* rc_x = x.data_ptr<float>();
        const float* rc_w = weight.data_ptr<float>();
        const float* rc_b = bias.data_ptr<float>();
        float* rc_y = y.data_ptr<float>();
        float* rc_p = partials_rc.data_ptr<float>();
        float rc_eps = static_cast<float>(eps);
        int rc_chunks = static_cast<int>(ch);
        int64_t rc_n = n;
        int64_t rc_rows = rows;
        int64_t rc_units = units;
        int64_t rc_chunk_units = per_chunk;
        void* rc_args[] = {
