    // the original L2-wave strategy where the normalize pass re-reads x.
    int max_bps = 0;
    cudaOccupancyMaxActiveBlocksPerMultiprocessor(
        &max_bps,
        layernorm_fused_kernel,
        threads,
        0);
    if (max_bps < 1) max_bps = 1;
    const int64_t max_coop = static_cast<int64_t>(max_bps) * num_sms;
    int64_t gr = group_budget / row_bytes;
    if (gr < 1) gr = 1;
    if (gr > rows) gr = rows;
    if (gr > max_coop) gr = max_coop;
    int64_t ch = max_coop / gr;
    if (ch < 1) ch = 1;
